# C04-Q01 P01 式(1)-(3)：三步相移的幅值恢复与二次谐波反例
import json
from pathlib import Path

import numpy as np

OUT = Path("输出")


def demodulate(intensity, theta):
    """式(2)：Z = 2/3 * sum(I_k * exp(-i theta_k))"""
    return 2.0 / 3.0 * np.sum(intensity * np.exp(-1j * theta), axis=-1)


def ideal(a, b, phi, theta):
    """式(1)：纯基频模型"""
    return a + b * np.cos(phi[:, None] + theta[None, :])


def independent(a, b, phi, theta):
    """第二条计算路径：实数形式的最小二乘"""
    i = ideal(a, b, phi, theta)
    s = np.sum(i * np.sin(theta), axis=-1)
    c = np.sum(i * np.cos(theta), axis=-1)
    return 2.0 / 3.0 * np.hypot(s, c)


def main():
    theta = 2 * np.pi * np.arange(3) / 3
    phi = np.linspace(0, 2 * np.pi, 721)
    z = demodulate(ideal(100.0, 2.0, phi, theta), theta)
    err = np.max(np.abs(np.abs(z) - 2.0) / 2.0)
    diff = np.max(np.abs(np.abs(z) - independent(100.0, 2.0, phi, theta)))
    OUT.mkdir(exist_ok=True)
    summary = {"selfcheck_passed": bool(diff < 1e-12), "max_err": float(err), "independent_diff": float(diff)}
    (OUT / "summary.json").write_text(json.dumps(summary, ensure_ascii=False, indent=2), encoding="utf-8")


if __name__ == "__main__":
    main()
